  'audience.privacy_heading': "Jak to działa i czego nigdy nie robi",
  'audience.privacy_1': "Własna kamera ekranu i detektor wbudowany w odtwarzacz wykrywają twarze patrzące na ekran. Wszystko odbywa się na ekranie.",
  'audience.privacy_2': "Żaden obraz, wideo, twarz ani nic, co mogłoby zidentyfikować osobę, nie jest zapisywane ani nie opuszcza ekranu. Każda klatka jest odrzucana zaraz po policzeniu.",
  'audience.privacy_3': "Wysyłane są tylko liczby: na minutę, ile osób było w polu widzenia, ile patrzyło i jak długo. Nikt nie jest rozpoznawany, śledzony między minutami ani nie ma przypisywanego wieku czy płci.",
  'audience.privacy_4': "Serwer odrzuca wszystko, co nie jest jedną z tych liczb, więc odtwarzacz nie mógłby wysłać więcej, nawet gdyby próbował.",
  'audience.privacy_notice_hint': "Poinformuj ludzi, gdzie prowadzisz liczenie. W docs/audience-counting.md jest gotowa do wydruku informacja. Zanim to włączysz, sprawdź przepisy obowiązujące tam, gdzie są Twoje ekrany (RODO, BIPA, CCPA i inne).",
