  'device.ignore_battery.toggle': "Zasilanie sieciowe (ignoruj baterię)",
  'device.native_video.toggle': "Natywne 4K (sprzętowa warstwa wideo)",
  'device.native_video.hint': "Używa sprzętowej warstwy wideo wyświetlacza do odtwarzania wideo na pełnym ekranie na obsługiwanych urządzeniach z Androidem. Lokalne obrazy większe niż 1080p są konwertowane do zapętlonego wariantu H.264. Dzięki temu klipy i obrazy 4K wyświetlają się w pełnej rozdzielczości na urządzeniach, których interfejs renderuje się w niższej rozdzielczości (Chromecast with Google TV, większość przystawek TV). Jeśli informacje o ekranie pokazują niższą rozdzielczość „UI” obok rozdzielczości ekranu (np. 3840x2160 (UI 1920x1080)), to ustawienie pozwala to obejść. Elementy wyświetlane w ten sposób pojawiają się i znikają bez przejścia, a na zrzutach ekranu są czarne. Obrócone ekrany, ściany wideo i układy ze strefami działają w zwykły sposób.",
  'device.ignore_battery.hint': "Dla telewizorów i paneli bez baterii, których płyta i tak zgłasza fałszywy poziom (np. stałe „42%, ładowanie”). Wymusza pusty odczyt baterii, dzięki czemu wszędzie, także w alertach, urządzenie jest traktowane jako zasilane z sieci. Zostaw wyłączone dla urządzeń z prawdziwą baterią.",
