  'support.desc': "Wpuść wsparcie ScreenTinker do tej instancji na ograniczony czas, tylko na twoją prośbę. Wygeneruj kod żądania i wyślij go do wsparcia; podpisany na jego podstawie token otwiera jedną, ograniczoną czasowo sesję, którą widzisz tutaj i możesz zakończyć w dowolnym momencie. Sesje wsparcia nie mogą zarządzać użytkownikami ani rozliczeniami ani niczego usuwać.",
