  'live_video.explain': "Pozwól operatorom oglądać na żywo strumień WebRTC z ekranu na karcie Teraz odtwarzane zamiast okresowych zrzutów ekranu. Wymaga skonfigurowanego na serwerze sidecara go2rtc oraz włączenia wideo na żywo dla poszczególnych ekranów. Ekrany, które nie mogą nadawać, nadal używają zrzutów ekranu.",
