  'approval.title': "Zatwierdzanie treści",
  'approval.explain': "Po włączeniu publikacja czegokolwiek w tej przestrzeni roboczej (playlist, pokazów slajdów, widżetów, układów, zastąpionych multimediów) wymaga najpierw zatwierdzenia przez recenzenta. Wersje robocze nigdy nie zmieniają tego, co wyświetlają ekrany. To, co jest dziś na żywo, nadal jest odtwarzane i nie wymaga zatwierdzenia wstecz.",
