  // #473 interactive web pages (webpage widget)
  'widget.web.interactive': "Interaktywna (kiosk samoobsługowy)",
  'widget.web.interactive_hint': "Odwiedzający mogą dotykać, przewijać i wypełniać formularze. Playlista jest wstrzymywana, gdy ktoś korzysta ze strony, a po jego odejściu strona się resetuje i wszystko, co zrobił, zostaje wymazane. Tylko pełny ekran. Pełna obsługa na Androidzie, w natywnych odtwarzaczach Windows i Raspberry Pi oraz na BrightSign; ekrany web, webOS i Tizen otrzymują ograniczoną wersję, która nie może wymazać danych witryny ani blokować innych witryn.",
  'widget.web.idle_timeout': "Resetuj po tylu sekundach bez dotyku",
  'widget.web.allowed_domains': "Inne witryny, które odwiedzający mogą otwierać",
  'widget.web.allowed_domains_ph': "np. checkout.example.com, maps.example.com",
  'widget.web.allowed_domains_hint': "Witryna samej strony jest zawsze dozwolona. Linki do innych miejsc są blokowane.",
  'widget.web.home_button': "Pokaż przycisk Start, gdy odwiedzający opuści stronę startową",
  'widget.web.idle_warning': "Odliczanie „Jesteś tam jeszcze?” przed resetem",
  'widget.web.idle_warning_off': "Wył. (reset od razu)",
  'widget.web.idle_warning_sec': "{n} s",
  'widget.web.idle_warning_hint': "Daje odwiedzającemu chwilę, aby dotknąć ekranu i kontynuować. Przydatne w sklepie; na stronie informacyjnej można to wyłączyć.",
  'widget.web.wipe_site_data': "Wymazuj pliki cookie i dane witryny po każdym odwiedzającym",
  'widget.web.wipe_site_data_hint': "Wyłącz dla stron informacyjnych, w których nie ma nic do ochrony (menu, cenniki, mapy): baner cookie i wybrany język zostaną wtedy zachowane. Każdy odwiedzający nadal otrzymuje świeżą stronę, historię i dane formularzy. Dane witryn są wspólne dla wszystkich stron internetowych na ekranie, więc wymazanie przez inny element na tym samym ekranie też je czyści. Odtwarzacze Windows i Raspberry Pi zachowują pliki cookie, ale nie dane witryn; BrightSign zawsze wymazuje.",
  'widget.web.keep_consent': "Zachowuj wybór zgody na pliki cookie między odwiedzającymi",
  'widget.web.keep_consent_hint': "Zachowywane są tylko pliki cookie zgody dozwolonych witryn. Logowania, koszyki i wszystko inne są nadal wymazywane po każdym odwiedzającym. Narzędzia zgody, które przechowują wybór w localStorage zamiast w pliku cookie, nadal będą pytać.",
  'widget.web.keep_cookie_names': "Inne nazwy plików cookie do zachowania",
  'widget.web.keep_cookie_names_ph': "np. shop_consent, cc_*",
  'widget.web.keep_cookie_names_hint': "Popularne narzędzia zgody (Cookiebot, OneTrust, IAB TCF, CookieYes, Complianz, Borlabs, iubenda, Didomi i inne) są już rozpoznawane. Końcowa * dopasowuje prefiks. Nigdy nie dodawaj tu pliku cookie logowania ani koszyka.",
  'widget.web.zoom_hint': "Powiększenie % powyżej dotyczy też strony interaktywnej: 150 sprawia, że witryna desktopowa układa się tak, jakby ekran miał dwie trzecie rozmiaru.",
  'device.event.web_error': "Błąd strony internetowej",
  'device.event.load_error': "Strona internetowa się nie wczytała",
  'device.event.http_error': "Strona internetowa zwróciła błąd",
  'device.event.renderer_gone': "Strona internetowa uległa awarii",
  'device.event.webview_too_old': "Strona internetowa wymaga nowszego WebView",
  'device.caps.web_interactive': "Interaktywne strony internetowe:",
  'device.caps.web_interactive_full': "pełna obsługa (witryna otwiera się we własnej przeglądarce; linki spoza dozwolonych witryn są blokowane, a wszystko jest wymazywane po każdym odwiedzającym)",
  'device.caps.web_interactive_framed': "ograniczona obsługa (witryna działa w ramce: witryny blokujące osadzanie w ramce pozostają puste, a ekran nie może blokować innych witryn ani wymazywać tego, co zostawi odwiedzający, więc logowanie może przetrwać reset)",
  'device.caps.web_interactive_none': "brak obsługi (strony interaktywne są wyświetlane jak zwykłe strony internetowe)",
  'widget.web.support': "Na ekranach w tej przestrzeni roboczej — pełna obsługa: {full}, ograniczona (bez wymazywania): {framed}, wyświetlanie jako zwykła strona: {none}.",
