  // Player rollouts (Platform; server lib/ota-rollout.js)
  'nav.platform.rollouts': "Wdrażanie odtwarzaczy",
  'platform.tab.rollouts': "Wdrażanie odtwarzaczy",
  'platform.rollouts.title': "Wdrażanie odtwarzaczy",
  'platform.rollouts.subtitle': "Nowe wersje odtwarzacza docierają do ekranów falami i zatrzymują się same, jeśli działają gorzej",
  'platform.rollouts.desc': "Nowy odtwarzacz na Androida, Pi lub Windows trafia najpierw do 10% ekranów danej platformy, potem do 50%, a potem do wszystkich — każda fala czeka, aż zaktualizowane ekrany będą działać prawidłowo. Jeśli zaktualizowane ekrany ulegają awariom lub gasną częściej niż pozostałe, wdrażanie samo się zatrzymuje, a ty otrzymujesz e-mail. Ekrany Pi i Windows, które pobrały zatrzymaną wersję, są cofane do poprzedniej. Androida nie można cofnąć do starszej wersji, więc tam zatrzymanie blokuje dalsze rozprzestrzenianie, a poprawką jest nowsza kompilacja. Ekrany na kanale beta oraz wymuszona aktualizacja pomijają fale.",
  'platform.rollouts.disabled': "Fale są wyłączone na tym serwerze (OTA_STAGED_ROLLOUT=off): każdy ekran od razu otrzymuje nową wersję.",
