  // 3.0: Simple help and the install-statistics question, now translated
  'simple.help.g1.title': "Podłącz ekran",
  'simple.help.g1.s1': "Na telewizorze, tablecie lub komputerze, którego chcesz użyć, otwórz odtwarzacz: zainstaluj aplikację na Androida albo otwórz stronę /player tej witryny w przeglądarce.",
  'simple.help.g1.s2': "Nie masz pod ręką telewizora? Otwórz odtwarzacz w innej karcie przeglądarki, aby wypróbować.",
  'simple.help.g1.s3': "Odtwarzacz pokazuje 6-cyfrowy kod. Tutaj wybierz „Dodaj ekran” i wpisz go.",
  'simple.help.g1.s4': "Nadaj ekranowi rozpoznawalną nazwę, np. „Witryna”.",
  'simple.help.g2.title': "Zmień to, co pokazuje ekran",
  'simple.help.g2.s1': "Wybierz „Zmień to, co pokazuje ekran” albo dotknij ekranu w sekcji „Twoje ekrany”.",
  'simple.help.g2.s2': "Wybierz „Zastąp”, aby pokazywać tylko nowe rzeczy, lub „Dodaj”, aby zachować to, co już jest odtwarzane.",
  'simple.help.g2.s3': "Prześlij zdjęcia lub filmy, wybierz przesłane wcześniej albo pokaż to samo co na innym ekranie.",
  'simple.help.g2.s4': "Ekran zaktualizuje się w ciągu kilku sekund.",
  'simple.help.g3.title': "Prześlij zdjęcia i filmy",
  'simple.help.g3.s1': "Wybierz „Prześlij zdjęcia” i wybierz dowolną liczbę plików albo je przeciągnij.",
  'simple.help.g3.s2': "Zaznacz ekrany, które mają je pokazywać, albo odznacz wszystkie, aby zachować je na później.",
  'simple.help.g3.s3': "Każde zdjęcie jest wyświetlane przez 10 sekund; filmy są odtwarzane do końca.",
  'simple.help.q1': "Czego mogę użyć jako ekranu?",
  'simple.help.a1': "Telewizorów, przystawek i tabletów z Androidem, Fire TV, telewizorów smart LG i Samsung, Raspberry Pi, komputerów z Windows i ChromeOS — lub dowolnego urządzenia z przeglądarką.",
  'simple.help.q2': "Ekran się nie zmienia. Co sprawdzić?",
  'simple.help.a2': "Upewnij się, że na stronie głównej ekran ma status „Odtwarza”. Jeśli widnieje „Offline”, sprawdź, czy urządzenie jest włączone i połączone z internetem; pobierze zmiany zaraz po ponownym połączeniu.",
  'simple.help.q3': "Co się stanie, gdy zabraknie internetu?",
  'simple.help.a3': "Ekrany przechowują treści lokalnie i odtwarzają je dalej. Nowe zmiany dotrą po przywróceniu połączenia.",
  'simple.help.q4': "Jakie pliki mogę przesłać?",
  'simple.help.a4': "Zdjęcia (JPEG, PNG, GIF, WebP) i filmy (najlepiej MP4), a także dźwięk. Pliki PDF można przesłać ze strony Treści w widoku zaawansowanym.",
  'simple.help.q5': "Jak zmienić nazwę ekranu lub go usunąć?",
  'simple.help.a5': "Przełącz na widok zaawansowany (w prawym górnym rogu), otwórz Ekrany, kliknij ekran, a następnie użyj opcji Zmień nazwę lub Usuń u góry jego strony.",
  'simple.help.q6': "Czy mogę pokazywać różne rzeczy o różnych porach dnia?",
  'simple.help.a6': "Tak — służy do tego Harmonogram w widoku zaawansowanym. Widok prosty zawsze pokazuje na ekranie te same treści, dopóki ich nie zmienisz.",
  'simple.help.trial_q': "Jak działa bezpłatny okres próbny?",
  'simple.help.trial_a': "Otrzymujesz 14 dni planu Pro ze wszystkimi funkcjami, bez podawania karty. Po jego zakończeniu przechodzisz na plan Free: nic nie zostaje usunięte, a ekrany ponad limit planu Free są wstrzymane, dopóki nie wybierzesz planu.",
  'stats.prompt.title': "Pomożesz pokazać, jak szeroko używany jest ScreenTinker?",
  'stats.prompt.body': "Większość instalacji jest prywatna, więc nie wiemy, ile jest ekranów. Udostępnianie wysyła losowy identyfikator, wersję i liczbę używanych ekranów — nic więcej, nigdy. Możesz to zmienić w dowolnej chwili w ustawieniach.",
  'stats.prompt.share': "Udostępnij",
  'stats.prompt.no': "Nie, dziękuję",
  'stats.prompt.thanks': "Dziękujemy — statystyki instalacji są udostępniane",
