  // 3.0: site cache
  'nav.site_caches': "Lokalne pamięci podręczne",
  'sitecache.intro': "Mały, stale włączony komputer w lokalizacji pobiera Twoje multimedia raz, a ekrany na miejscu pobierają je przez sieć lokalną zamiast przez internet.",
  'sitecache.how': "Ekrany sprawdzają każdy plik względem jego odcisku i wracają do tego serwera, jeśli pamięć podręczna jest wolna, niedostępna lub błędna, więc może ona oszczędzać transfer, ale nigdy nie wygasi ekranu. Odtwarzacze webowe używają jej od następnego uruchomienia; odtwarzacze Android od następnej aktualizacji playlisty. Zobacz docs/site-cache.md.",
  'sitecache.new': "Dodaj lokalną pamięć podręczną",
