  'migrate.key_note': "Klucz jest używany tylko na potrzeby tego importu. Jest przechowywany w postaci zaszyfrowanej najwyżej przez kilka godzin i usuwany po zakończeniu importu. Wystarczy dostęp do odczytu.",
