  'migrate.field.region': "Region",
  'migrate.how.xibo': "W Xibo otwórz Administration, a następnie Applications, i dodaj aplikację z zaznaczoną opcją „Client Credentials”. Skopiuj jej Client ID i Client Secret. Wpisz adres swojego CMS (ten, pod którym się logujesz), np. https://cms.example.com.",
  'migrate.how.yodeck': "W Yodeck otwórz Account Settings, Advanced Settings, API Tokens i wygeneruj token (plan Premium lub Enterprise). Wklej go w formacie label:token. Yodeck nie udostępnia przez API oryginalnie przesłanych obrazów i dokumentów: są one wymienione, aby można je było dodać importem zip. Filmy są przenoszone w wersji odtwarzanej przez Yodeck.",
  'migrate.how.optisigns': "OptiSigns ma API, ale nie dokumentuje żadnego sposobu pobierania plików, więc playlista dotarłaby pusta. Pobierz pliki z OptiSigns i użyj importu zip: jeden folder na playlistę lub plik playlists.csv.",
  'migrate.how.magicinfo': "API MagicINFO wyświetla treści i playlisty, ale nie dokumentuje sposobu pobierania plików, więc playlista dotarłaby pusta. Twoje ekrany Samsung mogą zostać: przełącz je na ScreenTinker w menu wyświetlacza (System > Play Via > URL Launcher, w nowszych modelach Custom App). Skopiuj pliki multimedialne z MagicINFO i użyj importu zip: jeden folder na playlistę lub plik playlists.csv.",
  'migrate.how.screencloud': "W ScreenCloud Studio otwórz Account Settings, a następnie kartę Developer, i utwórz token z uprawnieniami do odczytu. Wybierz pokazany tam region (EU lub US). ScreenCloud przechowuje reguły czasowe przy poszczególnych elementach kanału; są one wymieniane, ale nie importowane.",
  'migrate.how.anthias': "Wpisz adres urządzenia Anthias, np. http://192.168.1.20. Jeśli włączono uwierzytelnianie, wpisz nazwę użytkownika i hasło. Każde urządzenie jest importowane jako jeden ekran z jedną playlistą.",
  'migrate.how.screenly': "W Screenly otwórz Settings, Security, Tokens i dodaj token. Playlisty, etykiety i ekrany zostaną przeniesione; proste reguły dni i godzin staną się harmonogramami.",
  'migrate.how.generic_zip': "Prześlij plik zip z multimediami. Każdy folder staje się playlistą. Opcjonalnie dodaj playlists.csv (kolumny: playlist, file, duration, order) i screens.csv (kolumny: name, group, playlist).",
